// sectorData.ts — Real-Life VATSIM-DCS Sector & Airport Database
// Generated dynamically from UGGG, UBBA, UDDD, HECC, LLLL, LTXX, OAKX, OBBB, ORBB, LCCC, OIIX Sector Files
// & Official DCS me_db.DWE_airbases and me_db.Beacons Databases
// ════════════════════════════════════════════════════════════════════

export interface AirfieldBeacon {
  name: string
  frequency?: string
  channel?: string
  callsign?: string
  type: string
}

export interface Airfield {
  name: string
  lat: number
  lon: number
  icao?: string
  elevation?: number // in feet
  runways: {
    ident: string
    heading: number
    lat: number
    lon: number
    hasIls: boolean
    ilsFreq?: string
    ilsCall?: string
  }[]
  layout: [number, number][][] // Array of disjoint layout segments: [[lat1, lon1], [lat2, lon2]]
  frequencies?: string[] // Radio ATC frequencies
  tacan?: string // Airfield TACAN channel (e.g. 59X)
  beacons?: AirfieldBeacon[]
}

export interface Fix {
  name: string
  lat: number
  lon: number
  type: 'VOR' | 'FIX'
}

export interface Airway {
  name: string
  path: string[]
}

export interface SectorZone {
  name: string
  segments: [number, number][][] // Disjoint polyline segments: [[lat1, lon1], [lat2, lon2]]
}

export interface SectorData {
  theater: string
  airfields: Airfield[]
  fixes: Fix[]
  airways: Airway[]
  sectors: SectorZone[]
}

export function calculateOffsetLatLng(
  lat: number,
  lon: number,
  bearingDeg: number,
  distNm: number
): [number, number] {
  const R = 3440.065 // Earth radius in NM
  const distRad = distNm / R
  const brgRad = (bearingDeg * Math.PI) / 180
  const latRad = (lat * Math.PI) / 180
  const lonRad = (lon * Math.PI) / 180

  const nextLatRad = Math.asin(
    Math.sin(latRad) * Math.cos(distRad) +
      Math.cos(latRad) * Math.sin(distRad) * Math.cos(brgRad)
  )
  const nextLonRad =
    lonRad +
    Math.atan2(
      Math.sin(brgRad) * Math.sin(distRad) * Math.cos(latRad),
      Math.cos(distRad) - Math.sin(latRad) * Math.sin(nextLatRad)
    )

  return [
    (nextLatRad * 180) / Math.PI,
    ((nextLonRad * 180) / Math.PI + 540) % 360 - 180,
  ]
}

