// ── EMPTY STATIC THEATERS ─────────────────────────────────────────
const MARIANAS_DATA: SectorData = { theater: 'MARIANAS', airfields: [], fixes: [], airways: [], sectors: [] }
const KOLA_DATA: SectorData = { theater: 'KOLA', airfields: [], fixes: [], airways: [], sectors: [] }
const NEVADA_DATA: SectorData = { theater: 'NEVADA', airfields: [], fixes: [], airways: [], sectors: [] }
const NORMANDY_DATA: SectorData = { theater: 'NORMANDY', airfields: [], fixes: [], airways: [], sectors: [] }

export function getSectorDataForRegion(regionLabel: string): SectorData {
  const lbl = regionLabel.toUpperCase()
  if (lbl.includes('CAUCASUS')) {
    return CAUCASUS_DATA
  }
  if (lbl.includes('PERSIA') || lbl.includes('GULF') || lbl.includes('DUBAI') || lbl.includes('OMAN')) {
    return PERSIA_DATA
  }
  if (lbl.includes('SYRIA')) {
    return SYRIA_DATA
  }
  if (lbl.includes('SINAI') || lbl.includes('EGYPT')) {
    return SINAI_DATA
  }
  if (lbl.includes('MARIANAS')) {
    return MARIANAS_DATA
  }
  if (lbl.includes('KOLA')) {
    return KOLA_DATA
  }
  if (lbl.includes('NEVADA') || lbl.includes('NTTR')) {
    return NEVADA_DATA
  }
  if (lbl.includes('NORMANDY') || lbl.includes('CHANNEL')) {
    return NORMANDY_DATA
  }
  return CAUCASUS_DATA
}
